import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"解","description":"周易正义 - 解","frontmatter":{"title":"解","description":"周易正义 - 解"},"headers":[],"relativePath":"zh/classics/zhengyi/040.md","filePath":"zh/classics/zhengyi/040.md"}'),l={name:"zh/classics/zhengyi/040.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>雷水解</p></blockquote><blockquote><p>卦辞：利西南，无所往，其来复吉。有攸往，夙吉。</p></blockquote><blockquote><p>彖曰：解，险以动，动而免乎险，解。解，利西南，往得众也。其来复吉，乃得中也。有攸往夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之时大矣哉！</p></blockquote><h1 id="解" tabindex="-1">解 <a class="header-anchor" href="#解" aria-label="Permalink to “解”">​</a></h1><p>王弼：西南，众也。解难济险，利施於众。遇难不困于东北，故不言不利东北也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“解”者，卦名也。然解有两音，一音古买反，一音胡买反，“解”谓解难之初，“解”谓既解之后。《彖》称“动而免乎险”，明解众难之时，故先儒皆读为“解”。《序卦》云：“物不可以终难，故受之以解。解者，缓也。”然则“解”者，险难解，释物情舒缓，故为“解”也。“解利西南”者，西南坤位，坤是众也。施解於众，则所济者弘，故曰“解利西南”也。</p><h3 id="无所往-其来复-吉。有攸往-夙吉。-​" tabindex="-1">无所往，其来复，吉。有攸往，夙吉。 ​ <a class="header-anchor" href="#无所往-其来复-吉。有攸往-夙吉。-​" aria-label="Permalink to “无所往，其来复，吉。有攸往，夙吉。 ​”">​</a></h3><p>王弼：未有善於解难而迷於处安也。解之为义，解难而济厄者也。无难可往，以解来复则不失中。有难而往，则以速为吉者，无难则能复其中，有难则能济其厄也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“无所往”者，上言“解难济险，利施於众”。此下明救难之时，诫其可否。若无难可往，则以来复为吉。若有难可往，则以速赴为善，故云“无所往，其来复吉，有攸往夙吉”。设此诫者，褚氏云：“世有无事求功，故诫以无难宜静，亦有待败乃救，故诫以有难须速也。”</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="解-险以动-动而免乎险-解。-​" tabindex="-1">解，险以动，动而免乎险，解。 ​ <a class="header-anchor" href="#解-险以动-动而免乎险-解。-​" aria-label="Permalink to “解，险以动，动而免乎险，解。 ​”">​</a></h3><p>王弼：动乎险外，故谓之“免”。免险则解，故谓之“解”。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此就二体以释卦名。遇险不动，无由解难。动在险中，亦未能免咎。今动於险外，即见免脱於险，所以为“解”也。</p><h3 id="解-利西南-往得众也-其来复吉-乃得中也。-有攸往-夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲圻。-​" tabindex="-1">“解，利西南”，往得众也，“其来复吉”，乃得中也。“有攸往，夙吉”，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲圻。 ​ <a class="header-anchor" href="#解-利西南-往得众也-其来复吉-乃得中也。-有攸往-夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲圻。-​" aria-label="Permalink to ““解，利西南”，往得众也，“其来复吉”，乃得中也。“有攸往，夙吉”，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲圻。 ​”">​</a></h3><p>王弼：天地否结则雷雨不作，交通感散，雷雨乃作也。雷雨之作，则险厄者亨，否结者散，故“百果草木皆甲圻”也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>“解利西南”至“百果草木皆甲坼”。○正义曰：“解利西南往得众”者，“解”之为义，兼济为美。往之西南得施解於众，所以为利也。“其来复吉乃得中也”者，无难可解，退守静默，得理之中，故云“乃得中”也。“有攸往，夙吉，往有功也”者，解难能速，则不失其几，故“往有功也”。“天地解而雷雨作雷雨作，而百果草木皆甲圻”者，此因震、坎有雷雨之象，以广明“解”义。天地解缓，雷雨乃作。雷雨既作，百果草木皆孚甲开坼，莫不解散也。</p><h3 id="解之时大矣哉-​" tabindex="-1">解之时大矣哉！ ​ <a class="header-anchor" href="#解之时大矣哉-​" aria-label="Permalink to “解之时大矣哉！ ​”">​</a></h3><p>王弼：无圻而不释也。难解之时，非治难时，故不言用。体尽於解之名，无有幽隐，故不曰义。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：结叹解之大也。自天地至於草木，无不有“解”，岂非大哉！</p><h2 id="《象》曰-雷雨作-解。君子以赦过宥罪。-​" tabindex="-1">《象》曰：雷雨作，解。君子以赦过宥罪。 ​ <a class="header-anchor" href="#《象》曰-雷雨作-解。君子以赦过宥罪。-​" aria-label="Permalink to “《象》曰：雷雨作，解。君子以赦过宥罪。 ​”">​</a></h2><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：赦谓放免，过谓误失，宥谓宽宥，罪谓故犯，过轻则赦，罪重则宥，皆解缓之义也。</p><h2 id="初六-无咎-​" tabindex="-1">初六：无咎 ​ <a class="header-anchor" href="#初六-无咎-​" aria-label="Permalink to “初六：无咎 ​”">​</a></h2><p>王弼：“解”者，解也。屯难盘结，於是乎解也。处蹇难始解之初，在刚柔始散之际，将赦罪厄，以夷其险。处此之时，不烦於位而“无咎”也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：夫险难未夷，则贱弱者受害，然则蹇难未解之时，柔弱者不能无咎，否结既释之后，刚强者不复陵暴。初六，“处蹇难始解之初，在刚柔始散之际”，虽以柔弱处无位之地，逢此之时，不虑有咎，故曰“初六无咎”也。</p><h3 id="《象》曰-刚柔之际-义无咎也。-​" tabindex="-1">《象》曰：刚柔之际，义无咎也。 ​ <a class="header-anchor" href="#《象》曰-刚柔之际-义无咎也。-​" aria-label="Permalink to “《象》曰：刚柔之际，义无咎也。 ​”">​</a></h3><p>王弼：或有过咎，非其理也。“义”犹理也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“义无咎”者，“义”犹理也，刚柔既散，理必无咎，或有过咎，非理之当也，故曰“义无咎”也。○注“有过咎”至“义犹理也”。○正义曰：“或有过咎，非其理也”者，或本无此八字。</p><h2 id="九二-田获三狐-得黄矢-贞吉。-​" tabindex="-1">九二：田获三狐，得黄矢，贞吉。 ​ <a class="header-anchor" href="#九二-田获三狐-得黄矢-贞吉。-​" aria-label="Permalink to “九二：田获三狐，得黄矢，贞吉。 ​”">​</a></h2><p>王弼：狐者，隐伏之物也。刚中而应，为五所任，处於险中，知险之情，以斯解物，能获隐伏也，故曰：“田获三狐”也。黄，理中之称也。矢，直也。田而获三狐，得乎理中之道，不失枉直之实，能全其正者也，故曰“田获三狐，得黄矢，贞吉”也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“田获三狐”者，狐是隐伏之物，三为成数，举三言之，搜获欢尽。九二以刚居中而应於五，为五所任，处於险中，知险之情，以斯解险，无险不济，能获隐伏，如似田猎而获窟中之狐，故曰“田获三狐”。“得黄矢，贞吉”者，黄，中之称。矢，直也。田而获三狐，得乎无理中之道，不失枉直之实，能全其正者也，故曰“得黄矢贞吉”也。</p><h3 id="《象》曰-九二-贞吉-得中道也。-​" tabindex="-1">《象》曰：九二，“贞吉”，得中道也。 ​ <a class="header-anchor" href="#《象》曰-九二-贞吉-得中道也。-​" aria-label="Permalink to “《象》曰：九二，“贞吉”，得中道也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“得中道也”者，明九二位既不当，所以得“贞吉”者，由处於中，得乎理中之道故也。</p><h2 id="六三-负且乘-致寇至-贞吝。-​" tabindex="-1">六三：负且乘，致寇至，贞吝。 ​ <a class="header-anchor" href="#六三-负且乘-致寇至-贞吝。-​" aria-label="Permalink to “六三：负且乘，致寇至，贞吝。 ​”">​</a></h2><p>王弼：处非其位，履非其正，以附於四，用夫柔邪以自媚者也。乘二负四，以容其身。寇之来也，自已所致，虽幸而免，正之所贱也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“负且乘致寇至”者，六三，矢正无应，下乘於二，上附於四，即是用夫邪佞以自说媚者也。乘者，君子之器也。负者，小人之事也。施之於人，即在车骑之上，而负於物也。故寇盗知其非巳所有，於是竞欲夺之，故曰“负且乘致寇至”也。“贞吝”者，负乘之人，正其所鄙，故曰“贞吝”也。</p><h3 id="《象》曰-负且乘-亦可丑也。自我致戎-又谁咎也-​" tabindex="-1">《象》曰：负且乘，亦可丑也。自我致戎，又谁咎也？ ​ <a class="header-anchor" href="#《象》曰-负且乘-亦可丑也。自我致戎-又谁咎也-​" aria-label="Permalink to “《象》曰：负且乘，亦可丑也。自我致戎，又谁咎也？ ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“亦可丑也”者，天下之丑多矣，此是其一，故曰“亦可丑也”。“自我致戎，又谁咎也”者，言此寇虽由已之招，非是他人致此过咎，故曰“又谁咎也”。</p><h2 id="九四-解而拇-朋至斯孚。-​" tabindex="-1">九四：解而拇，朋至斯孚。 ​ <a class="header-anchor" href="#九四-解而拇-朋至斯孚。-​" aria-label="Permalink to “九四：解而拇，朋至斯孚。 ​”">​</a></h2><p>王弼：失位不正，而比於三，故三得附之为其拇也。三为之拇，则失初之应，故“解其拇”，然后朋至而信矣。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：而，汝也。拇，足大指也。履於不正，与三相比，三从下来附之，如指之附足，四有应在初。若三为之拇，则失初之应，故必“解其拇”，然后朋至而信，故曰“解而拇，朋至斯孚”。</p><h3 id="《象》曰-解而拇-未当位也。-​" tabindex="-1">《象》曰：“解而拇”，未当位也。 ​ <a class="header-anchor" href="#《象》曰-解而拇-未当位也。-​" aria-label="Permalink to “《象》曰：“解而拇”，未当位也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未当位”者，四若当位履正，即三为邪媚之身，不得附之也。既三不得附四，则无所解。今须解拇，由不当位也。</p><h2 id="六五-君子维有解-吉。有孚于小人。-​" tabindex="-1">六五：君子维有解，吉。有孚于小人。 ​ <a class="header-anchor" href="#六五-君子维有解-吉。有孚于小人。-​" aria-label="Permalink to “六五：君子维有解，吉。有孚于小人。 ​”">​</a></h2><p>王弼：居尊履中而应乎刚，可以有解而获吉矣。以君子之道解难释险，小人虽间，犹知服之而无怨矣。故曰“有孚于小人”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“君子维有解吉”者，六五，居尊履中而应於刚，是有君子之德。君子当此之时，可以解於险难。维，辞也。有解於难，所以获吉，故曰“君子维有解吉”也。“有孚于小人”者，以君子之道解难，则小人皆信服之，故曰“有孚于小人”也。</p><h3 id="《象》曰-君子有解-小人退也。-​" tabindex="-1">《象》曰：君子有解，小人退也。 ​ <a class="header-anchor" href="#《象》曰-君子有解-小人退也。-​" aria-label="Permalink to “《象》曰：君子有解，小人退也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：小人谓作难者，信君子之德，故退而畏服之。</p><h2 id="上六-公用射隼于高墉之上-获之-无不利。-​" tabindex="-1">上六：公用射隼于高墉之上，获之，无不利。 ​ <a class="header-anchor" href="#上六-公用射隼于高墉之上-获之-无不利。-​" aria-label="Permalink to “上六：公用射隼于高墉之上，获之，无不利。 ​”">​</a></h2><p>王弼：初为四应，二为五应，三不应上，失位负乘，处下体之上，故曰“高墉”。墉非隼之所处，高非三之所履，上六居动之上，为解之极，将解荒悖而除秽乱者也。故用射之，极则后动，成而后举，故必“获之”，而“无不利”也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>“上六”至“无不利”。○正义曰：隼者，贪残之鸟，鹯鹞之属。墉，墙也。六三失位负乘，不应於上，即是罪衅之人，故以譬於集。此借飞鸟为喻，而居下体之上，其犹隼处高墉。隼之为鸟，宜在山林，集於人家“高墉”，必为人所缴射，以譬六三处於高位，必当被人所诛讨。上六居动之上，为解之极，将解之荒悖而除秽乱，故用射之也。“极而后动，成而后举，故必获之，而无不利”，故曰“公用射隼于高墉之上，获之无不利”也。公宅臣之极。上六以阴居上，故谓之“公”也。</p><h3 id="《象》曰-公用射隼-以解悖也。-​" tabindex="-1">《象》曰：“公用射隼”，以解悖也。 ​ <a class="header-anchor" href="#《象》曰-公用射隼-以解悖也。-​" aria-label="Permalink to “《象》曰：“公用射隼”，以解悖也。 ​”">​</a></h3><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“解悖也”者，悖，逆也。六三失位负乘，不应於上，是悖逆之人也。上六居动之上，能除解六三之荒悖，故云“以解悖也”。</p>',70)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
